import pytest

from product.config import parse_limit


@pytest.mark.parametrize('value', [1, 100, '1', '100'])
def test_valid(value):
    assert parse_limit(value) == int(value)


@pytest.mark.parametrize('value', [True, False, 0, 101, -1, 1.5, None, '1.5', '', ' 2', '+2'])
def test_invalid(value):
    with pytest.raises(ValueError):
        parse_limit(value)

