import asyncio

import pytest

from product.service import score_summary


class Session:
    def __init__(self, present):
        self.present = present
        self.events = []

    async def get_evaluation(self, evaluation_id):
        self.events.append(('get', evaluation_id))
        return {'reuse_scores': True} if self.present else None

    async def execute(self, statement):
        self.events.append(('aggregate', statement))
        class Result:
            def one(self):
                return (0, 0, 0, 0, 0)
        return Result()


def test_present():
    session = Session(True)
    assert asyncio.run(score_summary(session, 'a')) == {'evaluation_id': 'a', 'reuse_scores': True, 'total': 0, 'succeeded': 0, 'failed': 0, 'skipped': 0, 'reused': 0}
    assert [event[0] for event in session.events] == ['get', 'aggregate']


def test_missing():
    session = Session(False)
    with pytest.raises(LookupError):
        asyncio.run(score_summary(session, 'a'))
    assert [event[0] for event in session.events] == ['get']
